"""
author:wjw
分析：动态规划+前缀和。
时间复杂度:O(n)
"""

class Solution:
    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:

        if s[-1] == '1':
            return False

        n = len(s)
        dp = [False] * n
        dp[0] = True

        presum = [0] * (n + 1)
        presum[1] = 1

        for i in range(1, n):
            if s[i] == '0':
                l = max(0, i - maxJump)
                r = i - minJump + 1

                if presum[r] - presum[l] > 0:
                    dp[i] = True

            presum[i + 1] = presum[i] + (1 if dp[i] else 0)

        return dp[n - 1]


s = ""
minJump = 5
maxJump = 99998
res = Solution().canReach(s, minJump, maxJump)
print(res)
